	bd_ = Ref{$PetscInt}()

    @chk ccall(
               (:DMAddBoundary, $petsc_library),
               PetscErrorCode,
               (CDM, DMBoundaryConditionType, Ptr{Cchar}, DMLabel, $PetscInt, Ptr{$PetscInt}, $PetscInt, $PetscInt, Ptr{$PetscInt}, Ptr{Cvoid}, Ptr{Cvoid}, Ptr{Cvoid}, Ptr{$PetscInt}),
