	is_ = Ref{Ptr{CIS}}()
	superdm_ = Ref{CDM}()

    @chk ccall(
               (:DMCreateSectionSuperDM, $petsc_library),
               PetscErrorCode,
               (Ptr{CDM}, $PetscInt, Ptr{Ptr{CIS}}, Ptr{CDM}),
               dms, len, is_, superdm_,
              )

	superdm = PetscDM(superdm_[], petsclib)
	is = is_[] == C_NULL ? IS{$PetscLib}[] : [IS(p, petsclib) for p in unsafe_wrap(Array, is_[], len; own = false)]

	return is,superdm
end 

