	netnum_ = Ref{$PetscInt}()

    @chk ccall(
               (:DMNetworkAddSubnetwork, $petsc_library),
               PetscErrorCode,
               (CDM, Ptr{Cchar}, $PetscInt, Ptr{$PetscInt}, Ptr{$PetscInt}),
               dm, name, ne, edgelist, netnum_,
              )

	netnum = netnum_[]

	return netnum
end 

