	sfz_ = Ref{PetscSF}()
	sfzr_ = Ref{PetscSF}()

    @chk ccall(
               (:DMPatchZoom, $petsc_library),
               PetscErrorCode,
               (CDM, MatStencil, MatStencil, MPI_Comm, Ptr{CDM}, Ptr{PetscSF}, Ptr{PetscSF}),
