	verticesAdjSaved_ = Ref{Ptr{$PetscInt}}()

    @chk ccall(
               (:DMPlexBuildFromCellSectionParallel, $petsc_library),
               PetscErrorCode,
               (CDM, $PetscInt, $PetscInt, $PetscInt, PetscSection, Ptr{$PetscInt}, Ptr{PetscSF}, Ptr{Ptr{$PetscInt}}),
               dm, numCells, numVertices, NVertices, cellSection, cells, vertexSF_, verticesAdjSaved_,
              )

	vertexSF = vertexSF_[]
	verticesAdjSaved = verticesAdjSaved_[]

	return vertexSF,verticesAdjSaved
end 

