@for_petsc function DMPlexGetCellCoordinates(petsclib::$UnionPetscLib, dm::AbstractPetscDM, cell::$PetscInt )
	isDG_ = Ref{PetscBool}()
	Nc_ = Ref{$PetscInt}()
	array_ = Ref{Ptr{$PetscScalar}}(C_NULL)
	coords_ = Ref{Ptr{$PetscScalar}}(C_NULL)

