	Nc = Nc_[]
	array = array_[]   # opaque pointer, passed back to DMPlexRestoreCellCoordinates
	coords = coords_[] == C_NULL ? $PetscScalar[] : unsafe_wrap(Array, coords_[], Nc; own = false)

	return isDG,Nc,array,coords
