end

@for_petsc function DMPlexSectionLoad(petsclib::$UnionPetscLib, dm::AbstractPetscDM, viewer::PetscViewer, sectiondm::AbstractPetscDM, globalToLocalPointSF::PetscSF )
	globalDofSF_ = Ref{PetscSF}()
	localDofSF_ = Ref{PetscSF}()

    @chk ccall(
               (:DMPlexSectionLoad, $petsc_library),
               PetscErrorCode,
               (CDM, PetscViewer, CDM, PetscSF, Ptr{PetscSF}, Ptr{PetscSF}),
               dm, viewer, sectiondm, globalToLocalPointSF, globalDofSF_, localDofSF_,
              )

	globalDofSF = globalDofSF_[]
	localDofSF = localDofSF_[]

	return globalDofSF,localDofSF
end 

