end

@for_petsc function DMPlexStratifyMigrationSF(petsclib::$UnionPetscLib, dm::AbstractPetscDM, sf::PetscSF )
	migrationSF_ = Ref{PetscSF}()

    @chk ccall(
               (:DMPlexStratifyMigrationSF, $petsc_library),
               PetscErrorCode,
               (CDM, PetscSF, Ptr{PetscSF}),
               dm, sf, migrationSF_,
              )

	migrationSF = migrationSF_[]

	return migrationSF
end 

