end

@for_petsc function DMPlexVecGetClosure(petsclib::$UnionPetscLib, dm::AbstractPetscDM, section::PetscSection, v::AbstractPetscVec, point::$PetscInt )
	csize_ = Ref{$PetscInt}()
	values_ = Ref{Ptr{$PetscScalar}}(C_NULL)

    @chk ccall(
               (:DMPlexVecGetClosure, $petsc_library),
               PetscErrorCode,
               (CDM, PetscSection, CVec, $PetscInt, Ptr{$PetscInt}, Ptr{Ptr{$PetscScalar}}),
               dm, section, v, point, csize_, values_,
              )

	csize = csize_[]
	csize = csize_[]
	values = values_[] == C_NULL ? $PetscScalar[] : unsafe_wrap(Array, values_[], csize; own = false)

	return csize,values
end 

