    # Restore the read-only Vec array that was obtained from VecGetArrayRead
    if array.ptr[] !== nothing
        vec_array = array.ptr[]::Vector{$PetscScalar}
        VecRestoreArrayRead(petsclib, vec, vec_array)
        array.ptr[] = nothing
    end

    return nothing
end

