end

@for_petsc function DMStagVecSplitToDMDA(petsclib::$UnionPetscLib, dm::AbstractPetscDM, vec::AbstractPetscVec, loc::DMStagStencilLocation, c::$PetscInt )
	pda_ = Ref{CDM}()
	pdavec_ = Ref{CVec}()

    @chk ccall(
               (:DMStagVecSplitToDMDA, $petsc_library),
               PetscErrorCode,
               (CDM, CVec, DMStagStencilLocation, $PetscInt, Ptr{CDM}, Ptr{CVec}),
               dm, vec, loc, c, pda_, pdavec_,
